import json,collections
OPEN={'pending','active','blocked'}; CLOSED={'done','rejected','dropped','cancelled'}
for f in ['/tmp/ajcr.json','/tmp/ajc.json']:
    d=json.load(open(f)); items=d['items']
    by={i['id']:i for i in items}
    kids=collections.defaultdict(list)
    for i in items:
        p=i.get('parent') or ''
        if p: kids[p].append(i)
    print('==',f,len(items),'warnings:',d.get('warnings'))
    for pid,ch in sorted(kids.items()):
        p=by.get(pid)
        if not p: continue
        if p['status'] in OPEN and all(c['status'] in CLOSED for c in ch):
            print('  PARENT-OPEN-ALL-KIDS-CLOSED:',pid,p['status'],[(c['id'].rsplit('.',1)[-1],c['status']) for c in ch])
        if p['status'] in CLOSED and any(c['status'] in OPEN for c in ch):
            print('  PARENT-CLOSED-OPEN-KIDS:',pid,p['status'],[(c['id'].rsplit('.',1)[-1],c['status']) for c in ch if c['status'] in OPEN])
    print('  statuses:',collections.Counter(i['status'] for i in items))
"
